// GENERATED by tmp/site-draft/export-site.mjs from tmp/design-system/effects.js.
// Procedural effects driven by tokens: image treatment (dithering/halftone),
// cellular-automaton motifs, and monochrome SVG charts. The tone and dither
// functions are pure and tested in Node; the render* functions need a DOM.

import { mulberry32 } from "./rng.js";

// ── Pure: procedural scenes (luminance in [0, 1], 1 = light) ─────────────

function hash2(x, y, seed) {
  let h = Math.imul(x, 374761393) ^ Math.imul(y, 668265263) ^ Math.imul(seed, 2246822519);
  h = Math.imul(h ^ (h >>> 13), 1274126177);
  return ((h ^ (h >>> 16)) >>> 0) / 4294967296;
}

function valueNoise(x, y, seed) {
  const xi = Math.floor(x);
  const yi = Math.floor(y);
  const s = (t) => t * t * (3 - 2 * t);
  const fx = s(x - xi);
  const fy = s(y - yi);
  const a = hash2(xi, yi, seed);
  const b = hash2(xi + 1, yi, seed);
  const c = hash2(xi, yi + 1, seed);
  const d = hash2(xi + 1, yi + 1, seed);
  return a + (b - a) * fx + (c - a) * fy + (a - b - c + d) * fx * fy;
}

export function fbm(x, y, seed, octaves = 5) {
  let sum = 0;
  let amp = 0.5;
  let norm = 0;
  for (let o = 0; o < octaves; o += 1) {
    sum += amp * valueNoise(x, y, seed + o * 17);
    norm += amp;
    x *= 2.03;
    y *= 2.03;
    amp *= 0.5;
  }
  return sum / norm;
}

const clamp01 = (v) => Math.min(1, Math.max(0, v));

export function scene(name, w, h, seed = 1) {
  const out = new Float32Array(w * h);
  const random = mulberry32(seed * 7919);
  const ox = random();
  const oy = random();
  for (let y = 0; y < h; y += 1) {
    for (let x = 0; x < w; x += 1) {
      const u = (x + 0.5) / w;
      const v = (y + 0.5) / h;
      const aspect = w / h;
      let L = 0;
      if (name === "gradient") {
        L = u;
      } else if (name === "mark") {
        const s = Math.min(w, h) * 0.6;
        const cx = w / 2;
        const cy = h / 2;
        const r = s / 2;
        const dx = x + 0.5 - cx;
        const dy = y + 0.5 - cy;
        const inCircle = dx * dx + dy * dy <= r * r;
        if (inCircle) L = 0.25;
        if (dx >= -r * 0.667 && dx < 0 && Math.abs(dy) <= r) L = 0.85;
        if (dx >= 0 && inCircle) L = 1;
      } else if (name === "sphere") {
        // A lit sphere on a table against a wall: the classic tone test.
        const horizon = 0.68;
        L = v < horizon ? 0.82 - 0.25 * v : 0.62 + 0.3 * (v - horizon);
        const sx = (u - 0.45 - (ox - 0.5) * 0.08) * aspect;
        const r = 0.27;
        const sy = v - (horizon + 0.12 - r);
        const shadow = (((u - 0.62) * aspect) / 0.36) ** 2 + ((v - horizon - 0.13) / 0.06) ** 2;
        if (shadow < 1) L *= 0.35 + 0.65 * shadow ** 2;
        const d2 = sx * sx + sy * sy;
        if (d2 < r * r) {
          const nz = Math.sqrt(r * r - d2) / r;
          const nx = sx / r;
          const ny = sy / r;
          const lambert = Math.max(0, -0.55 * nx - 0.6 * ny + 0.58 * nz);
          const spec = Math.max(0, -0.4 * nx - 0.5 * ny + 0.77 * nz) ** 30;
          const bounce = Math.max(0, ny) * 0.12;
          L = 0.04 + 0.82 * lambert + 0.5 * spec + bounce;
        }
      } else if (name === "organic") {
        const n = fbm(u * 4 * aspect + ox * 10, v * 4 + oy * 10, seed);
        const ridged = 1 - Math.abs(2 * fbm(u * 2.2 * aspect + 3, v * 2.2 + oy, seed + 99) - 1);
        L = clamp01((n * 0.6 + ridged ** 3 * 0.7) * 1.25 - 0.25);
      } else if (name === "portrait") {
        // An abstract bust under side light: shaded head, neck, shoulders.
        const hx = 0.5 + (ox - 0.5) * 0.14;
        const tilt = (oy - 0.5) * 0.3;
        L = 0.9 - 0.45 * u + 0.08 * fbm(u * 3, v * 3, seed + 5);
        const shade = (nx, ny) => {
          const nz = Math.sqrt(Math.max(0, 1 - nx * nx - ny * ny));
          return Math.max(0, -0.7 * nx - 0.3 * ny + 0.65 * nz);
        };
        const sh = [(u - hx) / 0.46, (v - 1.08) / 0.36];
        if (sh[0] ** 2 + sh[1] ** 2 < 1) L = 0.06 + 0.7 * shade(sh[0], sh[1]);
        if (Math.abs(u - hx) < 0.075 && v > 0.5 && v < 0.8) L = 0.05 + 0.35 * shade((u - hx) / 0.075, 0);
        const hd = [(u - hx) / 0.17 + tilt * (v - 0.38), (v - 0.38) / 0.22];
        if (hd[0] ** 2 + hd[1] ** 2 < 1) {
          L = 0.05 + 0.85 * shade(hd[0], hd[1]) + 0.06 * fbm(u * 14, v * 14, seed);
          if (hd[1] < -0.45 + 0.2 * hd[0] ** 2) L *= 0.25; // hair
        }
      }
      out[y * w + x] = clamp01(L);
    }
  }
  return out;
}

// ── Pure: dithering (returns Uint8Array, 1 = light) ──────────────────────

const BAYER8 = (() => {
  const m = [[0]];
  let n = 1;
  let mat = m;
  while (n < 8) {
    const next = Array.from({ length: n * 2 }, () => new Array(n * 2));
    for (let y = 0; y < n; y += 1) {
      for (let x = 0; x < n; x += 1) {
        const v = mat[y][x] * 4;
        next[y][x] = v;
        next[y][x + n] = v + 2;
        next[y + n][x] = v + 3;
        next[y + n][x + n] = v + 1;
      }
    }
    mat = next;
    n *= 2;
  }
  return mat.map((row) => row.map((v) => (v + 0.5) / 64));
})();

export function dither(L, w, h, mode) {
  const out = new Uint8Array(w * h);
  if (mode === "threshold") {
    for (let i = 0; i < L.length; i += 1) out[i] = L[i] >= 0.5 ? 1 : 0;
  } else if (mode === "bayer") {
    for (let y = 0; y < h; y += 1) for (let x = 0; x < w; x += 1) out[y * w + x] = L[y * w + x] > BAYER8[y & 7][x & 7] ? 1 : 0;
  } else if (mode === "diffusion") {
    // Atkinson: diffuses 6/8 of the error, so highlights and shadows clip
    // cleanly: the classic 1-bit Macintosh look.
    const e = Float32Array.from(L);
    for (let y = 0; y < h; y += 1) {
      for (let x = 0; x < w; x += 1) {
        const i = y * w + x;
        const bit = e[i] >= 0.5 ? 1 : 0;
        out[i] = bit;
        const err = (e[i] - bit) / 8;
        const spread = [[1, 0], [2, 0], [-1, 1], [0, 1], [1, 1], [0, 2]];
        for (const [dx, dy] of spread) {
          const xx = x + dx;
          const yy = y + dy;
          if (xx >= 0 && xx < w && yy < h) e[yy * w + xx] += err;
        }
      }
    }
  } else if (mode === "xerox") {
    // Photocopy: contrast pushed hard, toner grit and blotches, then a hard
    // threshold; dust specks of both colors and dark drum streaks on top.
    for (let y = 0; y < h; y += 1) {
      for (let x = 0; x < w; x += 1) {
        const i = y * w + x;
        const blotch = valueNoise(x / 9, y / 9, 3) - 0.5;
        const grit = hash2(x, y, 11) - 0.5;
        const streak = hash2(x, 0, 23) < 0.012 ? 0.4 * (0.6 + 0.4 * valueNoise(x, y / 40, 5)) : 0;
        const v = (L[i] - 0.5) * 2.2 + 0.5 + blotch * 0.35 + grit * 0.55 - streak;
        let bit = v >= 0.5 ? 1 : 0;
        if (hash2(x, y, 31) < 0.006) bit = 1 - bit;
        out[i] = bit;
      }
    }
  } else {
    throw new Error(`unknown dither mode ${mode}`);
  }
  return out;
}

/**
 * Horizontal tearing: bands of rows shifted sideways (wrapping), sized and
 * placed by a seeded hash. `amount` 0–1 scales both how many rows tear and
 * how far. Each row stays a rotation of itself, so tone is preserved.
 */
export function glitchRows(L, w, h, amount, seed = 1) {
  if (amount <= 0) return L;
  const out = new Float32Array(L.length);
  let shift = 0;
  let left = 0;
  for (let y = 0; y < h; y += 1) {
    if (left <= 0) {
      const torn = hash2(y, 1, seed) < 0.25 * amount;
      left = 1 + Math.floor(hash2(y, 2, seed) * Math.max(1, h * 0.08));
      shift = torn ? Math.round((hash2(y, 3, seed) - 0.5) * 2 * amount * w * 0.3) : 0;
    }
    left -= 1;
    const s = ((shift % w) + w) % w;
    for (let x = 0; x < w; x += 1) out[y * w + x] = L[y * w + ((x + s) % w)];
  }
  return out;
}

// ── Pure: 1D elementary automata and Life ────────────────────────────────

export function elementaryStep(row, rule) {
  const n = row.length;
  const next = new Uint8Array(n);
  for (let i = 0; i < n; i += 1) {
    const idx = (row[(i - 1 + n) % n] << 2) | (row[i] << 1) | row[(i + 1) % n];
    next[i] = (rule >> idx) & 1;
  }
  return next;
}

export function lifeStep(grid, w, h) {
  const next = new Uint8Array(w * h);
  for (let y = 0; y < h; y += 1) {
    const ym = ((y - 1 + h) % h) * w;
    const y0 = y * w;
    const yp = ((y + 1) % h) * w;
    for (let x = 0; x < w; x += 1) {
      const xm = (x - 1 + w) % w;
      const xp = (x + 1) % w;
      const n = grid[ym + xm] + grid[ym + x] + grid[ym + xp] + grid[y0 + xm] + grid[y0 + xp] + grid[yp + xm] + grid[yp + x] + grid[yp + xp];
      const alive = grid[y0 + x];
      next[y0 + x] = n === 3 || (alive && n === 2) ? 1 : 0;
    }
  }
  return next;
}

// ── DOM rendering ────────────────────────────────────────────────────────

function parseColor(css) {
  const m = css.match(/[\d.]+/g) ?? ["0", "0", "0"];
  return m.slice(0, 3).map(Number);
}

function lightDark(tokens) {
  const lum = (hex) => Number.parseInt(hex.slice(1, 3), 16) + Number.parseInt(hex.slice(3, 5), 16) + Number.parseInt(hex.slice(5, 7), 16);
  return lum(tokens.ink) >= lum(tokens.paper) ? [tokens.ink, tokens.paper] : [tokens.paper, tokens.ink];
}

const hexRgb = (hex) => [1, 3, 5].map((i) => Number.parseInt(hex.slice(i, i + 2), 16));

let userImage = null;
export function setUserImage(image) {
  userImage = image;
}

function sourceLuminance(canvas, w, h) {
  const sceneName = canvas.dataset.scene;
  const seed = Number(canvas.dataset.seed ?? 1);
  // A real photograph attached to this canvas (canvas.dsSource, e.g. a
  // portrait) wins over the testbed's global user image and the scenes.
  const source = canvas.dsSource ?? (sceneName !== "mark" && sceneName !== "gradient" ? userImage : null);
  if (source) {
    const c = document.createElement("canvas");
    c.width = w;
    c.height = h;
    const ctx = c.getContext("2d");
    const sw = source.naturalWidth ?? source.width;
    const sh = source.naturalHeight ?? source.height;
    const scale = Math.max(w / sw, h / sh);
    // Cover-crop; portraits bias the crop upward to keep faces in frame.
    const bias = canvas.classList.contains("portrait") ? 0.3 : 0.5;
    ctx.drawImage(source, (w - sw * scale) / 2, (h - sh * scale) * bias, sw * scale, sh * scale);
    const data = ctx.getImageData(0, 0, w, h).data;
    const L = new Float32Array(w * h);
    for (let i = 0; i < L.length; i += 1) L[i] = (0.2126 * data[i * 4] + 0.7152 * data[i * 4 + 1] + 0.0722 * data[i * 4 + 2]) / 255;
    return L;
  }
  return scene(sceneName, w, h, seed);
}

/**
 * Stretch tone so the `low`–`high` percentiles span 0–1. Portraits need it:
 * a face occupies a narrow band of the tonal range, and a dither can only
 * show tones that are spread across it.
 */
export function autoLevels(L, low = 0.02, high = 0.98) {
  const sorted = Float32Array.from(L).sort();
  const lo = sorted[Math.floor(sorted.length * low)];
  const hi = sorted[Math.min(sorted.length - 1, Math.floor(sorted.length * high))];
  if (hi - lo < 1e-3) return L;
  return L.map((v) => Math.min(1, Math.max(0, (v - lo) / (hi - lo))));
}

/** Render one .ds-image canvas with the current image treatment. */
export function renderImage(canvas, tokens) {
  const cssW = canvas.parentElement.clientWidth || 300;
  const aspect = Number(canvas.dataset.aspect ?? (canvas.classList.contains("portrait") ? 0.8 : 1.25));
  const cssH = Math.round(cssW / aspect);
  canvas.style.aspectRatio = String(aspect);
  // Portraits have their own treatment and pixel, and get tone stretched.
  const portrait = canvas.classList.contains("portrait");
  const own = portrait && tokens["portrait-image"] !== "same";
  const mode = own ? tokens["portrait-image"] : tokens.image;
  const pixel = own ? tokens["portrait-pixel"] : tokens.pixel;
  const source = (w, h) => (portrait ? autoLevels(sourceLuminance(canvas, w, h)) : sourceLuminance(canvas, w, h));
  const [light, dark] = lightDark(tokens).map(hexRgb);
  const ctx = canvas.getContext("2d");
  const seed = Number(canvas.dataset.seed ?? 1);
  if (mode === "threshold" || mode === "bayer" || mode === "diffusion" || mode === "xerox") {
    const w = Math.max(8, Math.round(cssW / pixel));
    const h = Math.max(8, Math.round(cssH / pixel));
    canvas.width = w;
    canvas.height = h;
    const bits = dither(glitchRows(source(w, h), w, h, tokens.glitch, seed), w, h, mode);
    const img = ctx.createImageData(w, h);
    for (let i = 0; i < bits.length; i += 1) img.data.set([...(bits[i] ? light : dark), 255], i * 4);
    ctx.putImageData(img, 0, 0);
    return;
  }
  const dpr = Math.min(2, globalThis.devicePixelRatio || 1);
  const w = Math.round(cssW * dpr);
  const h = Math.round(cssH * dpr);
  canvas.width = w;
  canvas.height = h;
  const L = glitchRows(source(w, h), w, h, tokens.glitch, seed);
  const img = ctx.createImageData(w, h);
  if (mode === "halftone") {
    // Square dots on a 45° screen, area ∝ darkness. Rectilinear by design.
    const cell = pixel * 2 * dpr;
    const cos = Math.SQRT1_2;
    for (let y = 0; y < h; y += 1) {
      for (let x = 0; x < w; x += 1) {
        const ru = (x * cos + y * cos) / cell;
        const rv = (-x * cos + y * cos) / cell;
        const cu = Math.floor(ru) + 0.5;
        const cv = Math.floor(rv) + 0.5;
        // Sample tone at the cell center.
        const sx = Math.min(w - 1, Math.max(0, Math.round((cu - cv) * cos * cell)));
        const sy = Math.min(h - 1, Math.max(0, Math.round((cu + cv) * cos * cell)));
        const darkness = 1 - L[sy * w + sx];
        const half = Math.sqrt(darkness) / 2;
        const inside = Math.abs(ru - cu) < half && Math.abs(rv - cv) < half;
        img.data.set([...(inside ? dark : light), 255], (y * w + x) * 4);
      }
    }
  } else {
    for (let i = 0; i < L.length; i += 1) {
      const c = dark.map((d, k) => Math.round(d + (light[k] - d) * L[i]));
      img.data.set([...c, 255], i * 4);
    }
  }
  ctx.putImageData(img, 0, 0);
}

/** The D mark through the image treatment at a fixed cell count. */
export function renderPixelMark(canvas, tokens) {
  const n = Number(canvas.dataset.cells);
  canvas.width = n;
  canvas.height = n;
  const L = new Float32Array(n * n);
  // scene() draws the mark at 60 % of the square; crop so it fills this one.
  const big = scene("mark", Math.round(n / 0.6), Math.round(n / 0.6));
  const m = Math.round(n / 0.6);
  const off = Math.round((m - n) / 2);
  for (let y = 0; y < n; y += 1) for (let x = 0; x < n; x += 1) L[y * n + x] = big[(y + off) * m + x + off];
  // L is the ink fraction (the supplied frames keep the disc in ink on
  // either ground), so a set bit is ink and a clear bit is paper.
  const mode = tokens.image === "none" || tokens.image === "halftone" ? "bayer" : tokens.image;
  const bits = dither(L, n, n, mode);
  const [ink, paper] = [hexRgb(tokens.ink), hexRgb(tokens.paper)];
  const ctx = canvas.getContext("2d");
  const img = ctx.createImageData(n, n);
  for (let i = 0; i < bits.length; i += 1) img.data.set([...(bits[i] ? ink : paper), 255], i * 4);
  ctx.putImageData(img, 0, 0);
}

// ── Motifs ───────────────────────────────────────────────────────────────

const motifs = new Map(); // canvas → state

function motionAllowed(tokens) {
  return tokens.motion !== "none" && !globalThis.matchMedia?.("(prefers-reduced-motion: reduce)").matches;
}

export function setupMotif(canvas, tokens) {
  const kind = canvas.dataset.force ?? tokens.motif;
  const rect = canvas.getBoundingClientRect();
  const cssW = Math.max(1, rect.width);
  const cssH = Math.max(1, rect.height);
  // Specimen tiles show the automaton itself, so cap their cell size.
  const cell = canvas.dataset.force ? Math.min(tokens.cell, 4) : tokens.cell;
  const color = parseColor(getComputedStyle(canvas).color);
  const ctx = canvas.getContext("2d");
  const state = { kind, ctx, color, canvas, frame: 0, role: canvas.dataset.motifRole };
  const seed = [...(canvas.dataset.motifRole ?? "x")].reduce((a, c) => a * 31 + c.charCodeAt(0), 7);
  const random = mulberry32(seed);
  if (kind === "grid") {
    const dpr = Math.min(2, globalThis.devicePixelRatio || 1);
    canvas.width = Math.round(cssW * dpr);
    canvas.height = Math.round(cssH * dpr);
    ctx.clearRect(0, 0, canvas.width, canvas.height);
    ctx.fillStyle = `rgb(${color.join(" ")} / 0.35)`;
    const step = cell * dpr;
    for (let x = 0; x <= canvas.width; x += step) ctx.fillRect(Math.round(x), 0, Math.max(1, dpr * 0.5), canvas.height);
    for (let y = canvas.height; y >= 0; y -= step) ctx.fillRect(0, Math.round(y), canvas.width, Math.max(1, dpr * 0.5));
    ctx.fillStyle = `rgb(${color.join(" ")})`;
    for (let x = 0; x <= canvas.width; x += step * 4) for (let y = canvas.height; y >= 0; y -= step * 4) ctx.fillRect(Math.round(x) - dpr, Math.round(y) - dpr, 3 * dpr, 3 * dpr);
    motifs.set(canvas, state);
    return state;
  }
  const w = Math.max(4, Math.round(cssW / cell));
  const h = Math.max(2, Math.round(cssH / cell));
  canvas.width = w;
  canvas.height = h;
  Object.assign(state, { w, h });
  if (kind === "life") {
    const grid = new Uint8Array(w * h);
    // Denser toward the top: the field dissolves toward the text below.
    for (let y = 0; y < h; y += 1) for (let x = 0; x < w; x += 1) grid[y * w + x] = random() < (canvas.dataset.force || state.role === "video" ? 0.35 : 0.42 * (1 - y / h) ** 1.2) ? 1 : 0;
    state.grid = grid;
    for (let i = 0; i < 12; i += 1) state.grid = lifeStep(state.grid, w, h);
    state.random = random;
  } else if (kind === "rule30" || kind === "rule110") {
    state.rule = kind === "rule30" ? 30 : 110;
    let row = new Uint8Array(w);
    if (kind === "rule30") row[Math.floor(w * 0.62)] = 1;
    else for (let i = 0; i < w; i += 1) row[i] = random() < 0.5 ? 1 : 0;
    const rows = [];
    for (let i = 0; i < h + (kind === "rule30" ? 0 : 40); i += 1) {
      rows.push(row);
      row = elementaryStep(row, state.rule);
    }
    state.rows = rows.slice(-h);
    state.next = row;
  }
  drawMotif(state);
  motifs.set(canvas, state);
  return state;
}

function drawMotif(state) {
  const { ctx, w, h, color } = state;
  if (!w) return;
  const img = ctx.createImageData(w, h);
  const set = (i) => img.data.set([...color, 255], i * 4);
  if (state.kind === "life") {
    for (let i = 0; i < w * h; i += 1) if (state.grid[i]) set(i);
  } else if (state.rows) {
    state.rows.forEach((row, y) => row.forEach((on, x) => on && set(y * w + x)));
  }
  ctx.putImageData(img, 0, 0);
}

function tickMotif(state) {
  if (state.kind === "life") {
    state.grid = lifeStep(state.grid, state.w, state.h);
    // Inject a little noise along the top edge so the field never dies out.
    for (let x = 0; x < state.w; x += 1) for (let y = 0; y < Math.min(3, state.h); y += 1) if (state.random() < 0.08) state.grid[y * state.w + x] = 1;
  } else if (state.rows) {
    state.rows.shift();
    state.rows.push(state.next);
    state.next = elementaryStep(state.next, state.rule);
  } else return;
  drawMotif(state);
}

let timer = 0;
let lastTokens = null;
const visible = new Set();
const observer = typeof IntersectionObserver === "function" ? new IntersectionObserver((entries) => {
  for (const entry of entries) entry.isIntersecting ? visible.add(entry.target) : visible.delete(entry.target);
}) : null;

export function setupMotifs(root, tokens) {
  lastTokens = tokens;
  motifs.clear();
  for (const canvas of root.querySelectorAll("canvas.motif")) {
    setupMotif(canvas, tokens);
    observer?.observe(canvas);
  }
  clearInterval(timer);
  if (motionAllowed(tokens)) {
    const interval = tokens.motion === "steps" ? 125 : 70;
    timer = setInterval(() => {
      for (const [canvas, state] of motifs) {
        if (state.role === "video" && !canvas.closest("[data-video]")?.classList.contains("playing")) continue;
        if (!observer || visible.has(canvas)) tickMotif(state);
      }
    }, interval);
  }
}

export function advanceMotif(canvas, steps = 1) {
  const state = motifs.get(canvas);
  if (state) for (let i = 0; i < steps; i += 1) tickMotif(state);
}

// ── Grain overlay ───────────────────────────────────────────────────────
// A still grain is a CSS background (apply.js). Moving grain needs a canvas:
// a 128² black/white tile, repeated over a fixed full-viewport canvas at one
// canvas pixel per grain pixel. drift flips a few percent of the tile per
// tick, so the noise slowly boils; static regenerates it all, ~20×/s, at a
// random offset so the tile seam never settles.

const GRAIN_N = 128;
let grain = null;

function xorshift(state) {
  state.s ^= state.s << 13;
  state.s ^= state.s >>> 17;
  state.s ^= state.s << 5;
  return (state.s >>> 0) / 4294967296;
}

function sizeGrain() {
  const win = grain.canvas.ownerDocument.defaultView;
  const w = Math.ceil(win.innerWidth / grain.size);
  const h = Math.ceil(win.innerHeight / grain.size);
  if (grain.canvas.width !== w || grain.canvas.height !== h) {
    grain.canvas.width = w;
    grain.canvas.height = h;
  }
}

function paintGrain() {
  const { bits, image, tctx, ctx, canvas } = grain;
  for (let i = 0; i < bits.length; i += 1) {
    const v = bits[i] ? 255 : 0;
    image.data[i * 4] = v;
    image.data[i * 4 + 1] = v;
    image.data[i * 4 + 2] = v;
    image.data[i * 4 + 3] = 255;
  }
  tctx.putImageData(image, 0, 0);
  const pattern = ctx.createPattern(grain.tile, "repeat");
  if (grain.mode === "static" && pattern.setTransform && globalThis.DOMMatrix) {
    pattern.setTransform(new DOMMatrix().translate(Math.floor(xorshift(grain.rng) * GRAIN_N), Math.floor(xorshift(grain.rng) * GRAIN_N)));
  }
  ctx.fillStyle = pattern;
  ctx.fillRect(0, 0, canvas.width, canvas.height);
}

function stepGrain() {
  const { bits, rng } = grain;
  if (grain.mode === "static") {
    for (let i = 0; i < bits.length; i += 1) bits[i] = xorshift(rng) < 0.5 ? 1 : 0;
  } else {
    const flips = Math.round(bits.length * 0.03);
    for (let k = 0; k < flips; k += 1) {
      const i = Math.floor(xorshift(rng) * bits.length);
      bits[i] = 1 - bits[i];
    }
  }
  paintGrain();
}

/** Start, retune, or stop the moving-grain canvas for a token set. */
export function setupGrain(doc, tokens) {
  const mode = tokens.grain > 0 ? tokens["grain-motion"] : "none";
  if (grain) clearInterval(grain.timer);
  if (mode === "none") {
    grain?.canvas.remove();
    grain = null;
    return;
  }
  if (!grain) {
    const canvas = doc.createElement("canvas");
    canvas.className = "ds-grain";
    canvas.setAttribute("aria-hidden", "true");
    doc.body.append(canvas);
    const tile = doc.createElement("canvas");
    tile.width = GRAIN_N;
    tile.height = GRAIN_N;
    const tctx = tile.getContext("2d");
    grain = { canvas, tile, tctx, ctx: canvas.getContext("2d"), image: tctx.createImageData(GRAIN_N, GRAIN_N), bits: new Uint8Array(GRAIN_N * GRAIN_N), rng: { s: 0x2545f491 }, timer: 0 };
    for (let i = 0; i < grain.bits.length; i += 1) grain.bits[i] = xorshift(grain.rng) < 0.5 ? 1 : 0;
    doc.defaultView.addEventListener("resize", () => grain && (sizeGrain(), paintGrain()));
  }
  grain.mode = mode;
  grain.size = tokens["grain-size"];
  sizeGrain();
  paintGrain();
  if (doc.defaultView.matchMedia?.("(prefers-reduced-motion: reduce)").matches) return;
  grain.timer = setInterval(() => !doc.hidden && stepGrain(), mode === "static" ? 50 : 120);
}

// ── Charts (SVG) ─────────────────────────────────────────────────────────

const SVG = "http://www.w3.org/2000/svg";
function el(name, attrs = {}, text) {
  const node = document.createElementNS(SVG, name);
  for (const [k, v] of Object.entries(attrs)) node.setAttribute(k, v);
  if (text !== undefined) node.textContent = text;
  return node;
}

function tooltip(figure) {
  let tip = figure.querySelector(".tooltip");
  if (!tip) {
    tip = document.createElement("div");
    tip.className = "tooltip";
    tip.hidden = true;
    figure.append(tip);
  }
  return tip;
}

function hover(figure, svg, node, text, x, y) {
  const tip = tooltip(figure);
  node.setAttribute("tabindex", "0");
  node.setAttribute("aria-label", text);
  const show = () => {
    const box = svg.getBoundingClientRect();
    const fig = figure.getBoundingClientRect();
    const scale = box.width / svg.viewBox.baseVal.width;
    tip.textContent = text;
    tip.style.left = `${box.left - fig.left + x * scale}px`;
    tip.style.top = `${box.top - fig.top + y * scale}px`;
    tip.hidden = false;
  };
  const hide = () => (tip.hidden = true);
  node.addEventListener("pointerenter", show);
  node.addEventListener("pointerleave", hide);
  node.addEventListener("focus", show);
  node.addEventListener("blur", hide);
}

const DATA = {
  bars: [["Undergraduate", 9], ["Alumni", 4], ["Faculty", 2], ["Graduate", 1]],
  line: [0.52, 0.55, 0.61, 0.6, 0.66, 0.7, 0.69, 0.74, 0.77, 0.79],
};

export function renderChart(figure) {
  figure.querySelector("svg")?.remove();
  const kind = figure.dataset.chart;
  const W = 400;
  let svg;
  if (kind === "bars") {
    const rows = DATA.bars;
    const rowH = 30;
    const H = rows.length * rowH + 22;
    svg = el("svg", { viewBox: `0 0 ${W} ${H}`, role: "img", "aria-label": `Bar chart: ${rows.map(([k, v]) => `${k} ${v}`).join(", ")}` });
    const x0 = 112;
    const max = 10;
    const sx = (v) => ((W - x0 - 30) * v) / max;
    for (let t = 0; t <= max; t += 5) {
      svg.append(el("line", { class: "grid", x1: x0 + sx(t), x2: x0 + sx(t), y1: 0, y2: rows.length * rowH }));
      svg.append(el("text", { x: x0 + sx(t), y: H - 4, "text-anchor": "start" }, String(t)));
    }
    rows.forEach(([name, value], i) => {
      const y = i * rowH + 6;
      svg.append(el("text", { x: 0, y: y + 13 }, name));
      const bar = el("rect", { class: `mark${i === 0 ? " hl" : ""}`, x: x0, y, width: sx(value), height: rowH - 12 });
      svg.append(bar);
      svg.append(el("text", { class: "value", x: x0 + sx(value) + 6, y: y + 13 }, String(value)));
      hover(figure, svg, bar, `${name}: ${value}`, x0 + sx(value) / 2, y);
    });
    svg.append(el("line", { class: "axis", x1: x0, x2: x0, y1: 0, y2: rows.length * rowH }));
  } else if (kind === "line") {
    const H = 220;
    const [l, r, t, b] = [30, 64, 8, 22];
    svg = el("svg", { viewBox: `0 0 ${W} ${H}`, role: "img", "aria-label": "Line chart: recall accuracy rises from 0.52 to 0.79 over ten trials; chance is 0.5" });
    const sx = (i) => l + ((W - l - r) * i) / 9;
    const sy = (v) => t + (H - t - b) * (1 - (v - 0.4) / 0.5);
    for (const v of [0.4, 0.6, 0.8]) {
      svg.append(el("line", { class: "grid", x1: l, x2: W - r, y1: sy(v), y2: sy(v) }));
      svg.append(el("text", { x: 0, y: sy(v) + 4 }, v.toFixed(1)));
    }
    svg.append(el("line", { class: "axis", x1: l, x2: W - r, y1: H - b, y2: H - b }));
    for (const i of [0, 4, 9]) svg.append(el("text", { x: sx(i), y: H - 6 }, `T${i + 1}`));
    svg.append(el("line", { class: "line ref", x1: l, x2: W - r, y1: sy(0.5), y2: sy(0.5) }));
    svg.append(el("text", { x: W - r + 6, y: sy(0.5) + 4 }, "chance"));
    svg.append(el("path", { class: "line", d: DATA.line.map((v, i) => `${i ? "L" : "M"}${sx(i)},${sy(v)}`).join("") }));
    DATA.line.forEach((v, i) => {
      const last = i === DATA.line.length - 1;
      const dot = el("rect", { class: `mark${last ? " hl" : ""}`, x: sx(i) - 3, y: sy(v) - 3, width: 6, height: 6 });
      svg.append(dot);
      hover(figure, svg, dot, `Trial ${i + 1}: ${v.toFixed(2)}`, sx(i), sy(v) - 4);
    });
    svg.append(el("text", { class: "value", x: W - r + 6, y: sy(0.79) + 4 }, "0.79"));
  } else if (kind === "dots") {
    const H = 240;
    const [l, r, t, b] = [30, 12, 8, 22];
    svg = el("svg", { viewBox: `0 0 ${W} ${H}`, role: "img", "aria-label": "Scatter plot of task time against accuracy for 40 participants; one outlier is highlighted" });
    const random = mulberry32(42);
    const sx = (v) => l + (W - l - r) * v;
    const sy = (v) => t + (H - t - b) * (1 - v);
    for (const v of [0.25, 0.5, 0.75]) svg.append(el("line", { class: "grid", x1: l, x2: W - r, y1: sy(v), y2: sy(v) }));
    svg.append(el("line", { class: "axis", x1: l, x2: W - r, y1: H - b, y2: H - b }));
    svg.append(el("text", { x: l, y: H - 4 }, "time →"));
    svg.append(el("text", { x: 0, y: t + 8 }, "acc."));
    for (let i = 0; i < 40; i += 1) {
      const x = 0.15 + random() * 0.7;
      const y = Math.min(0.95, Math.max(0.05, 0.85 - 0.6 * x + (random() - 0.5) * 0.3));
      const dot = el("rect", { class: "dot", x: sx(x) - 4, y: sy(y) - 4, width: 8, height: 8 });
      svg.append(dot);
      hover(figure, svg, dot, `P${String(i + 1).padStart(2, "0")}: ${Math.round(120 + x * 500)} s, ${y.toFixed(2)}`, sx(x), sy(y) - 6);
    }
    const out = el("rect", { class: "dot hl", x: sx(0.9) - 4, y: sy(0.88) - 4, width: 8, height: 8 });
    svg.append(out);
    svg.append(el("text", { class: "value", x: sx(0.9) - 8, y: sy(0.88) + 18, "text-anchor": "end" }, "P41"));
    hover(figure, svg, out, "P41: 570 s, 0.88 (outlier)", sx(0.9), sy(0.88) - 6);
  }
  figure.append(svg);
}

export { lastTokens };
